//! Public typed inventory actions, life/protection checks and success-only feedback.
use gielinor_world::{held_item_conversion::Rule,inventory::{Item,StackType},simulation::{World,PlayerData,ActorId,Action,WorldEvent},stats::Stats,hits::{Hit,Target,Style},CoordGrid};
const PAIRS:[(i32,i32,u8);9]=[(33,36,2),(32,38,2),(594,596,6),(4531,4529,3),(4534,4532,3),(4524,4522,3),(4539,4537,3),(4550,4548,3),(5013,5014,4)];
fn fixture(i:usize)->(World,ActorId){let(lit,unlit,op)=PAIRS[i];let mut w=World::default();w.collision.allocate(3200,3200,0);let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_current(11,0);stats.set_current(12,0);let mut d=PlayerData::new(1,"Independent inventory extinguish".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);d.xp_rate_hundreds=0;
 for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:if s==17 || s==26{lit}else{1931},count:1,vars:0})).unwrap();}w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,true).unwrap();w.empty_containers.insert(lit,Rule{output:unlit,members:true,button_operation:op,message:Some("Independent successful conversion")});w.drain_events();(w,a)}
#[test]
fn one_hundred_sixty_two_actual_conversion_cases_cover_unsigned_hp_queued_death_and_atomic_refusals(){let mut cases=0;for i in 0..9{for mode in 0..18{let(mut w,a)=fixture(i);let(lit,unlit,_)=PAIRS[i];let mut claim=lit;
 match mode{0=>{},1=>w.data_mut(a).unwrap().stats.set_current(3,200u8 as i8),2=>w.data_mut(a).unwrap().stats.set_current(3,0),3=>{w.queue_hit(Target::Player(a),Hit{display:None,source:None,style:Style::Typeless,damage:20},1).unwrap();w.tick().unwrap();assert_eq!(w.data(a).unwrap().stats.current(3),0);assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::DeathRequested(Target::Player(id)) if *id==a)));w.data_mut(a).unwrap().stats.set_current(3,10);},4=>w.set_membership(a,false).unwrap(),5=>{w.data_mut(a).unwrap().inventory.restore_slot(17,Some(Item{id:1931,count:1,vars:0})).unwrap();},6=>{w.data_mut(a).unwrap().inventory.restore_slot(17,Some(Item{id:lit,count:1,vars:1})).unwrap();},7=>{w.data_mut(a).unwrap().inventory.restore_slot(17,Some(Item{id:lit,count:2,vars:0})).unwrap();},8=>{w.object_types.dummy.insert(unlit);},9=>{w.object_types.dummy.insert(lit);},10=>w.data_mut(a).unwrap().inventory.placeholders=true,11=>w.data_mut(a).unwrap().inventory.stack=StackType::Always,12=>w.delay_player(a,3).unwrap(),13=>w.set_modal_open(a,true).unwrap(),14=>w.request_logout(a).unwrap(),15=>claim=999999,16=>w.empty_containers.get_mut(&lit).unwrap().output=lit,_=>{w.data_mut(a).unwrap().inventory.restore_slot(17,None).unwrap();}}
 let before=w.data(a).unwrap().clone();w.drain_events();let _=w.submit(a,Action::ConvertHeldItem{slot:17,item:claim});w.tick().unwrap();let events=w.drain_events();let mut expected=before.inventory.clone();if mode<=1{expected.restore_slot(17,Some(Item{id:unlit,count:1,vars:0})).unwrap();}assert_eq!(w.data(a).unwrap().inventory,expected,"pair{i} mode{mode}");assert_eq!(w.data(a).unwrap().stats,before.stats,"pair{i} mode{mode}");assert_eq!(events.iter().filter(|e|matches!(e,WorldEvent::GameMessage{text,..} if text=="Independent successful conversion")).count(),usize::from(mode<=1));assert!(!events.iter().any(|e|matches!(e,WorldEvent::SkillAdvanced{..}|WorldEvent::PlayerCombatAnimation{..})));assert_eq!(w.data(a).unwrap().inventory.get(26).unwrap().id,lit);
 if mode<=1{w.submit(a,Action::ConvertHeldItem{slot:17,item:lit}).unwrap();w.tick().unwrap();assert_eq!(w.data(a).unwrap().inventory,expected);assert_eq!(w.data(a).unwrap().stats,before.stats);assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::GameMessage{text,..} if text=="Independent successful conversion")));}
 cases+=1;
 }}assert_eq!(cases,162);}
